style.css:
/* Apply to domain: google.com */

/* 1. Turn the entire Google background yellow */
html, body, div, main, header, footer {
  background-color: yellow !important;
  background-image: none !important;
}

/* 2. Style Google search buttons and bar like a retro meme page */
input[type="text"], textarea, [role="search"] {
  background-color: #ffffff !important;
  border: 3px solid #000000 !important;
  box-shadow: 4px 4px 0px #000000 !important;
}

button, input[type="submit"], [role="button"] {
  background-color: #ff0000 !important;
  color: #ffffff !important;
  font-family: "Impact", sans-serif !important;
  border: 2px solid #000000 !important;
  box-shadow: 3px 3px 0px #000000 !important;
  transform: rotate(-2deg);
}

/* 3. Drop elements off the screen with gravity */
body > * {
  animation: belugaDrop 2.5s cubic-bezier(0.55, 0.085, 0.68, 0.53) forwards !important;
}

@keyframes belugaDrop {
  0% {
    transform: translateY(0px) rotate(0deg);
  }
  15% {
    transform: translateY(-20px) rotate(-5deg);
  }
  100% {
    transform: translateY(120vh) rotate(360deg);
    opacity: 0;
  }
}
